7: void TraceDecimator::decimateMinMax(const float* inputdBm,
8:                                     int inputCount,
9:                                     int targetPixels,
10:                                     std::vector<float>& outputdBm)
11: {
12:     if (!inputdBm || inputCount <= 0 || targetPixels <= 0) {
13:         outputdBm.clear();
14:         return;
15:     }
16: 
17:     // If input is smaller than or equal to target pixels, no decimation needed
18:     if (inputCount <= targetPixels) {
19:         outputdBm.assign(inputdBm, inputdBm + inputCount);
20:         return;
21:     }
22: 
23:     outputdBm.resize(static_cast<size_t>(targetPixels * 2));
24: 
25:     double pointsPerPixel = static_cast<double>(inputCount) / targetPixels;
26: 
27:     for (int px = 0; px < targetPixels; ++px) {
28:         int startIdx = static_cast<int>(std::floor(px * pointsPerPixel));
29:         int endIdx   = static_cast<int>(std::floor((px + 1) * pointsPerPixel));
30: 
31:         startIdx = std::clamp(startIdx, 0, inputCount - 1);
32:         endIdx   = std::clamp(endIdx, startIdx + 1, inputCount);
33: 
34:         float minVal = inputdBm[startIdx];
35:         float maxVal = inputdBm[startIdx];
36: 
37:         for (int i = startIdx + 1; i < endIdx; ++i) {
38:             minVal = std::min(minVal, inputdBm[i]);
39:             maxVal = std::max(maxVal, inputdBm[i]);
40:         }
41: 
42:         // Pair min and max for each pixel column
43:         outputdBm[static_cast<size_t>(px * 2)]     = minVal;
44:         outputdBm[static_cast<size_t>(px * 2 + 1)] = maxVal;
45:     }
46: }
