21: void SpectrogramWidget::initColorLut()
22: {
23:     if (s_lutInitialized) return;
24: 
25:     // Thermal / Jet Heatmap Palette: Blue -> Cyan -> Green -> Yellow -> Red -> White
26:     for (int i = 0; i < 256; ++i) {
27:         float val = i / 255.0f;
28:         int r = 0, g = 0, b = 0;
29: 
30:         if (val < 0.2f) { // Deep Blue -> Blue
31:             b = static_cast<int>(128 + val * 5 * 127);
32:         } else if (val < 0.4f) { // Blue -> Cyan
33:             b = 255;
34:             g = static_cast<int>((val - 0.2f) * 5 * 255);
35:         } else if (val < 0.6f) { // Cyan -> Green -> Yellow
36:             g = 255;
37:             b = static_cast<int>(255 - (val - 0.4f) * 5 * 255);
38:             r = static_cast<int>((val - 0.4f) * 5 * 255);
39:         } else if (val < 0.8f) { // Yellow -> Orange -> Red
40:             r = 255;
41:             g = static_cast<int>(255 - (val - 0.6f) * 5 * 255);
42:         } else { // Red -> White
43:             r = 255;
44:             g = static_cast<int>((val - 0.8f) * 5 * 255);
45:             b = static_cast<int>((val - 0.8f) * 5 * 255);
46:         }
47: 
48:         // Format ARGB32 uint32_t
49:         s_colorLut[i] = (0xFFu << 24) | (r << 16) | (g << 8) | b;
50:     }
51: 
52:     s_lutInitialized = true;
53: }
