55: uint32_t SpectrogramWidget::mapPowerToRgb(float dBm) const
56: {
57:     // Map dBm range [-110, RefLevel] to [0, 255]
58:     float minDb = m_refLeveldBm - 100.0f;
59:     float maxDb = m_refLeveldBm;
60:     float norm = (dBm - minDb) / (maxDb - minDb);
61:     int idx = std::clamp(static_cast<int>(norm * 255.0f), 0, 255);
62:     return s_colorLut[idx];
63: }
