73: void SpectrogramWidget::onNewFrame(const rtsa::ProcessedFrame& frame)
74: {
75:     if (frame.dBm.empty() || isHidden()) return;
76: 
77:     int plotW = width() - kMarginLeft - kMarginRight;
78:     int plotH = height() - kMarginTop - kMarginBottom;
79: 
80:     if (plotW <= 10 || plotH <= 10) return;
81: 
82:     // Check if QImage size matches
83:     if (m_waterfallImage.size() != QSize(plotW, plotH)) {
84:         m_waterfallImage = QImage(plotW, plotH, QImage::Format_RGB32);
85:         m_waterfallImage.fill(QColor(0x0e, 0x10, 0x1c));
86:     }
87: 
88:     // 1. Fast Line Shift (move existing waterfall lines down by 1 row)
89:     int bytesPerLine = m_waterfallImage.bytesPerLine();
90:     uchar* bits = m_waterfallImage.bits();
91:     std::memmove(bits + bytesPerLine, bits, bytesPerLine * (plotH - 1));
92: 
93:     // 2. Render new line 0 (top row) with LUT lookup
94:     uint32_t* line0 = reinterpret_cast<uint32_t*>(m_waterfallImage.scanLine(0));
95:     int srcSize = static_cast<int>(frame.dBm.size());
96: 
97:     for (int x = 0; x < plotW; ++x) {
98:         int srcIdx = (x * srcSize) / plotW;
99:         srcIdx = std::clamp(srcIdx, 0, srcSize - 1);
100:         line0[x] = mapPowerToRgb(frame.dBm[srcIdx]);
101:     }
102: 
103:     update();
104: }
