174: QString SpectrogramWidget::formatFrequency(double hz) const
175: {
176:     double absHz = std::abs(hz);
177:     if (absHz >= 1e9) return QString("%1 G").arg(hz / 1e9, 0, 'f', 3);
178:     if (absHz >= 1e6) return QString("%1 M").arg(hz / 1e6, 0, 'f', 2);
179:     if (absHz >= 1e3) return QString("%1 k").arg(hz / 1e3, 0, 'f', 1);
180:     return QString("%1 Hz").arg(hz, 0, 'f', 0);
181: }
