119: void DataProcessor::processFrame(const SpectrumFrame& raw)
120: {
121:     std::lock_guard<std::mutex> lock(m_mutex);
122: 
123:     // Detect dropped frames
124:     if (m_lastFrameId > 0 && raw.frameId > m_lastFrameId + 1) {
125:         uint64_t dropped = raw.frameId - m_lastFrameId - 1;
126:         m_dropCount += dropped;
127:     }
128:     m_lastFrameId = raw.frameId;
129: 
130:     int count = std::min(raw.size, m_fftSize);
131: 
132:     // Step 1: TracePipeline processing (ClearWrite, MaxHold, MinHold, Average)
133:     m_tracePipeline.process(raw.data.data(), count, m_processeddBm);
134: 
135:     // Step 2: Marker triggers
136:     if (m_pendingPeakSearch) {
137:         m_markerEngine.searchPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
138:         m_pendingPeakSearch = false;
139:     }
140:     if (m_pendingNextPeak) {
141:         m_markerEngine.searchNextPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
142:         m_pendingNextPeak = false;
143:     }
144:     if (m_pendingNextPeakRight) {
145:         m_markerEngine.searchNextPeakRight(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
146:         m_pendingNextPeakRight = false;
147:     }
148:     if (m_pendingNextPeakLeft) {
149:         m_markerEngine.searchNextPeakLeft(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
150:         m_pendingNextPeakLeft = false;
151:     }
152:     if (m_pendingMinSearch) {
153:         m_markerEngine.searchMin(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
154:         m_pendingMinSearch = false;
155:     }
156: 
157:     // Continuous Peak: auto-search peak every frame
158:     if (m_continuousPeakEnabled) {
159:         m_markerEngine.searchPeak(m_continuousPeakMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
160:     }
161: 
162:     // Step 3: Update existing markers
163:     m_markerEngine.updateMarkers(m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
164: 
165:     // Step 4: Min-Max Pixel Decimation (Compress 4096 points -> 800 pixel buckets * 2 = 1600 points)
166:     static std::vector<float> decimateddBm;
167:     const int targetPixels = 800;
168:     TraceDecimator::decimateMinMax(m_processeddBm.data(), count, targetPixels, decimateddBm);
169: 
170:     // Step 5: Prepare ProcessedFrame
171:     ProcessedFrame result;
172:     result.frameId   = raw.frameId;
173:     result.dropCount = m_dropCount;
174: #if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
175:     result.dBm.assign(decimateddBm.begin(), decimateddBm.end());
176: #else
177:     result.dBm = QVector<float>::fromStdVector(decimateddBm);
178: #endif
179: 
180:     m_processedCount++;
181: 
182:     emit frameReady(result);
183:     emit markersUpdated();
184: }
