25: bool FsmController::transitionTo(FsmState newState)
26: {
27:     if (m_state == newState) return true;
28: 
29:     // Check transition validity
30:     bool valid = false;
31: 
32:     switch (m_state) {
33:     case FsmState::Idle:
34:         valid = (newState == FsmState::Running ||
35:                  newState == FsmState::SingleSweep ||
36:                  newState == FsmState::Calibrating ||
37:                  newState == FsmState::Fault);
38:         break;
39:     case FsmState::Running:
40:         valid = (newState == FsmState::Idle ||
41:                  newState == FsmState::SingleSweep ||
42:                  newState == FsmState::Calibrating ||
43:                  newState == FsmState::Fault);
44:         break;
45:     case FsmState::SingleSweep:
46:         valid = (newState == FsmState::Idle ||
47:                  newState == FsmState::Running ||
48:                  newState == FsmState::Fault);
49:         break;
50:     case FsmState::Calibrating:
51:         valid = (newState == FsmState::Idle ||
52:                  newState == FsmState::Fault);
53:         break;
54:     case FsmState::Fault:
55:         valid = (newState == FsmState::Idle); // Only allowed to transition back to IDLE via resetFault
56:         break;
57:     }
58: 
59:     if (!valid) {
60:         Logger::warning(TAG, QString("Invalid transition: %1 -> %2")
61:                                  .arg(stateString())
62:                                  .arg(static_cast<int>(newState)));
63:         return false;
64:     }
65: 
66:     FsmState oldState = m_state;
67:     m_state = newState;
68: 
69:     Logger::info(TAG, QString("State changed: %1 -> %2").arg(stateString()).arg(stateString()));
70:     emit stateChanged(m_state, oldState);
71:     return true;
