225: QString MarkerCard::formatFrequency(double hz) const
226: {
227:     double absHz = std::abs(hz);
228:     QString prefix = (hz < 0) ? "-" : "";
229: 
230:     if (absHz >= 1e9)
231:         return QString("%1%2 G").arg(prefix).arg(absHz / 1e9, 0, 'f', 3);
232:     if (absHz >= 1e6)
233:         return QString("%1%2 M").arg(prefix).arg(absHz / 1e6, 0, 'f', 2);
234:     if (absHz >= 1e3)
235:         return QString("%1%2 k").arg(prefix).arg(absHz / 1e3, 0, 'f', 1);
236:     return QString("%1%2 Hz").arg(prefix).arg(absHz, 0, 'f', 0);
237: }
